"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([[477],{10:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"test","metadata":{"permalink":"/blog/test","source":"@site/blog/test.mdx","title":"Test","description":"\u53d1\u987a\u4e30\u7b2c\u4e09\u65b9\u7b2c\u4e09\u65b9\u58eb\u5927\u592b","date":"2023-05-26T09:54:13.000Z","formattedDate":"2023\u5e745\u670826\u65e5","tags":[{"label":"Capslock","permalink":"/blog/tags/capslock"}],"readingTime":0.09,"hasTruncateMarker":false,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=32&v=4","key":"timfan"}],"frontMatter":{"slug":"test","title":"Test","authors":["timfan"],"tags":["Capslock"]},"nextItem":{"title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","permalink":"/blog/tree-views"}},"content":"\u53d1\u987a\u4e30\u7b2c\u4e09\u65b9\u7b2c\u4e09\u65b9\u58eb\u5927\u592b\\n\\nimport WeChatFollowCard from \'@site/src/components/WeChatFollowCard\'\\n\\n<WeChatFollowCard />"},{"id":"tree-views","metadata":{"permalink":"/blog/tree-views","source":"@site/blog/2023-05-26-tree-views-in-css/index.mdx","title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","description":"\u4e00\u4e2a\u6811\u72b6\u7ed3\u6784\u7684\u89c6\u56fe\u53ef\u4ee5\u4ec5\u4ec5\u7531 HTML \u548c CSS \u4ee3\u7801\u6765\u5b9e\u73b0\u800c\u4e0d\u7528\u501f\u52a9 JavaScript\u3002\u7f51\u9875\u7684\u65e0\u969c\u788d\u8bbf\u95ee\u529f\u80fd\u4f1a\u5c06\u6811\u72b6\u89c6\u56fe\u89c6\u4e3a\u5d4c\u5957\u7684\u5e76\u5305\u542b\u5176\u5b83\u7ec4\u4ef6\u5185\u5bb9\u7684\u5217\u8868\uff0c\u5e76\u4e14\u81ea\u52a8\u652f\u6301\u6807\u51c6\u952e\u76d8\u4ea4\u4e92\u3002","date":"2023-05-26T00:00:00.000Z","formattedDate":"2023\u5e745\u670826\u65e5","tags":[{"label":"\u6811\u72b6","permalink":"/blog/tags/\u6811\u72b6"},{"label":"\u89c6\u56fe","permalink":"/blog/tags/\u89c6\u56fe"}],"readingTime":7.495,"hasTruncateMarker":false,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=32&v=4","key":"timfan"}],"frontMatter":{"slug":"tree-views","title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","authors":["timfan"],"tags":["\u6811\u72b6","\u89c6\u56fe"]},"prevItem":{"title":"Test","permalink":"/blog/test"},"nextItem":{"title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","permalink":"/blog/detecting-caps-lock"}},"content":"\u4e00\u4e2a\u6811\u72b6\u7ed3\u6784\u7684\u89c6\u56fe\u53ef\u4ee5\u4ec5\u4ec5\u7531 HTML \u548c CSS \u4ee3\u7801\u6765\u5b9e\u73b0\u800c\u4e0d\u7528\u501f\u52a9 JavaScript\u3002\u7f51\u9875\u7684\u65e0\u969c\u788d\u8bbf\u95ee\u529f\u80fd\u4f1a\u5c06\u6811\u72b6\u89c6\u56fe\u89c6\u4e3a\u5d4c\u5957\u7684\u5e76\u5305\u542b\u5176\u5b83\u7ec4\u4ef6\u5185\u5bb9\u7684\u5217\u8868\uff0c\u5e76\u4e14\u81ea\u52a8\u652f\u6301\u6807\u51c6\u952e\u76d8\u4ea4\u4e92\u3002\\n\\nimport styles from \\"./style.module.css\\"\\nimport clsx from \'clsx\';\\nexport const TreeViews = ({ ulClsName, expandAll }) => (\\n  <ul className={clsx(styles.tree, styles[ulClsName])}>\\n    <li>\\n      <details open>\\n        <summary>Giant planets</summary>\\n        <ul>\\n          <li>\\n            <details open={ expandAll }>\\n              <summary>Gas giants</summary>\\n              <ul>\\n                <li>Jupiter</li>\\n                <li>Saturn</li>\\n              </ul>\\n            </details>\\n          </li>\\n          <li>\\n            <details open={ expandAll }>\\n              <summary>Ice giants</summary>\\n              <ul>\\n                <li>Uranus</li>\\n                <li>Neptune</li>\\n              </ul>\\n            </details>\\n          </li>\\n        </ul>\\n      </details>\\n    </li>\\n  </ul>\\n)\\n\\n<TreeViews ulClsName=\'displaytree\' />\\n\\n### HTML \u4ee3\u7801\u7ed3\u6784\\n\\n\u9996\u5148\u6dfb\u52a0\u5982\u4e0b\u7684\u5d4c\u5957\u7684\u5217\u8868\u7ed3\u6784\u4ee3\u7801\uff1a\\n\\n``` html\\n<ul>\\n  <li>\\n    Giant planets\\n    <ul>\\n      <li>\\n        Gas giants\\n        <ul>\\n          <li>Jupiter</li>\\n          <li>Saturn</li>\\n        </ul>\\n      </li>\\n      <li>\\n        Ice giants\\n        <ul>\\n          <li>Uranus</li>\\n          <li>Neptune</li>\\n        </ul>\\n      </li>\\n    </ul>\\n  </li>\\n</ul>\\n```\\n\\n\u4e3a\u4e86\u65b9\u4fbf\u8bbe\u7f6e\u6837\u5f0f\uff0c\u6211\u4eec\u7ed9\u6700\u5916\u5c42\u7684 `<ul>` \u5143\u7d20\u6dfb\u52a0\u4e00\u4e2a\u7c7b\u540d\u3002\u7b2c\u4e00\u5c42\u7684 `<li>` \u5143\u7d20\u4e0b\u9762\u90fd\u5d4c\u5957\u4e86\u4e00\u4e2a\u5217\u8868\uff0c\u4e3a\u4e86\u5b9e\u73b0\u5c55\u5f00\u7684\u6548\u679c\uff0c\u6211\u4eec\u5c06 `<li>` \u91cc\u9762\u7684\u5143\u7d20\u90fd\u653e\u5728 `<details>` \u548c `<summary>` \u4e0b\u9762\u3002\\n\u7136\u540e\u901a\u8fc7 `open` \u5c5e\u6027\u6765\u8bbe\u7f6e\u9ed8\u8ba4\u5c55\u5f00\u7684\u5d4c\u5957\u5217\u8868\u3002\\n\\n``` html\\n<ul class=\\"tree\\">\\n  <li>\\n    <details open>\\n      <summary>Giant planets</summary>\\n      <ul>\\n        <li>\\n          <details>\\n            <summary>Gas giants</summary>\\n            <ul>\\n              <li>Jupiter</li>\\n              <li>Saturn</li>\\n            </ul>\\n          </details>\\n        </li>\\n        <li>\\n          <details>\\n            <summary>Ice giants</summary>\\n            <ul>\\n              <li>Uranus</li>\\n              <li>Neptune</li>\\n            </ul>\\n          </details>\\n        </li>\\n      </ul>\\n    </details>\\n  </li>\\n</ul>\\n```\\n\\n\u5982\u4e0b\uff0c\u8fd9\u662f\u6ca1\u6709\u6dfb\u52a0\u4efb\u4f55\u6837\u5f0f\u7684\uff1a\\n\\n<TreeViews ulClsName=\'none\' />\\n\\n\u6d4f\u89c8\u5668\u4e3a `<details>` \u5143\u7d20\u63d0\u4f9b\u4e86\u63d0\u4f9b\u5c55\u5f00\u548c\u6298\u53e0\u5d4c\u5957\u5217\u8868\u7684\u80fd\u529b\uff0c\u4f46\u662f\u9879\u76ee\u7b26\u53f7\u548c\u7bad\u5934\u7b26\u53f7\u90fd\u663e\u793a\u5bb9\u6613\u8ba9\u4eba\u4ea7\u751f\u56f0\u60d1\u3002\u6211\u4eec\u8fdb\u884c\u7ec4\u5408\u6539\u53d8\u4e0b\u6837\u5f0f\u3002\\n\\n### \u81ea\u5b9a\u4e49\u6837\u5f0f\\n\\n\u6709\u4e24\u4e2a\u7ef4\u5ea6\u4f1a\u5f71\u54cd\u6811\u89c6\u56fe\u7684\u5e03\u5c40\uff1a\u884c\u95f4\u8ddd\uff08\u7b49\u4e8e\u6587\u672c\u7684\u884c\u9ad8\uff09\u548c\u5217\u8868\u7b26\u53f7\u7684\u534a\u5f84\u3002 \u9996\u5148\u6211\u4eec\u7ed9\u8fd9\u4e24\u4e2a\u7ef4\u5ea6\u7684\u6570\u636e\u901a\u8fc7 CSS \u81ea\u5b9a\u4e49\u5c5e\u6027\u5b9a\u4e49\u5e38\u91cf\u4f9b\u540e\u9762\u4f7f\u7528\uff1a\\n\\n``` css\\n.tree{\\n  --spacing : 1.5rem;\\n  --radius  : 10px;\\n}\\n```\\n\\n\u867d\u7136\u6211\u4eec\u901a\u5e38\u4f1a\u6839\u636e\u6587\u672c\u5927\u5c0f\u4f7f\u7528\u76f8\u5bf9\u5355\u4f4d\u6765\u7f29\u653e\u7528\u6237\u754c\u9762\u63a7\u4ef6\uff0c\u4f46\u5bf9\u4e8e\u5217\u8868\u7b26\u53f7\u8fd8\u662f\u4f7f\u7528\u4e86\u5408\u7406\u7684\u56fa\u5b9a\u5927\u5c0f\uff0c\u907f\u514d\u592a\u5927\u540e\u8005\u592a\u5c0f\u3002\\n\\n#### \u5de6\u8fb9\u8ddd\\n\\n\u63a5\u7740\u6211\u4eec\u6765\u7ed9\u5217\u8868\u6539\u53d8\u4e0b\u6837\u5f0f\uff0c\u5728\u5de6\u4fa7\u6dfb\u52a0\u4e00\u4e2a\u5185\u8fb9\u8ddd\uff0c\u4e3a\u6811\u72b6\u7684\u7ebf\u6761\u548c\u5c55\u5f00\u6536\u7f29\u7b26\u53f7\u817e\u51fa\u7a7a\u95f4\u3002\\n\\n``` css\\n.tree li{\\n  display      : block;\\n  position     : relative;\\n  padding-left : calc(2 * var(--spacing) - var(--radius) - 2px);\\n}\\n\\n.tree ul{\\n  margin-left  : calc(var(--radius) - var(--spacing));\\n  padding-left : 0;\\n}\\n```\\n\\n\u4e3a `li` \u6807\u7b7e\u8bbe\u7f6e `display: block` \u6d88\u9664\u9ed8\u8ba4\u7684\u5217\u8868\u7b26\u53f7\uff0c\u5de6\u8fb9\u8ddd\u7684\u503c\u662f\u901a\u8fc7\u4e0a\u9762\u7684\u5e38\u91cf\u8ba1\u7b97\u800c\u6765\u3002\u4e0b\u9762\u5bf9\u5d4c\u5957\u7684 `ul` \u8bbe\u7f6e\u8d1f\u8fb9\u8ddd\u6765\u8865\u507f\u5bf9 `li` \u8bbe\u7f6e\u7684\u7f29\u8fdb\u3002\\n\\n\u6709\u4e86\u4e0a\u9762\u7684\u6837\u5f0f\uff0c\u5728\u7ed9\u6240\u6709\u7684\u9ed8\u8ba4\u5217\u8868\u5c55\u5f00\uff0c\u5c31\u662f\u4e0b\u9762\u7684\u6837\u5f0f\uff1a\\n\\n<TreeViews ulClsName=\'displayPaddingTree\' expandAll={ true } />\\n\\n#### \u5782\u76f4\u7ebf\\n\\n\u63a5\u4e0b\u6765\u6211\u4eec\u6dfb\u52a0\u6811\u7ed3\u6784\u7684\u5782\u76f4\u7ebf\uff0c\u8fd9\u4e9b\u5782\u76f4\u7ebf\u6784\u6210\u5c06\u6bcf\u4e2a\u5217\u8868\u9879\u4ece\u5782\u76f4\u65b9\u5411\u4e32\u8054\u8d77\u6765\uff1a\\n\\n<TreeViews ulClsName=\'displayLineTree\' expandAll={ true } />\\n\\n#### \u6c34\u5e73\u7ebf\\n\\n\u6211\u4eec\u4f7f\u7528 CSS \u751f\u6210\u4e00\u6761\u6c34\u5e73\u7ebf\u5c06\u5782\u76f4\u7ebf\u548c\u5217\u8868\u524d\u7684\u7b26\u53f7\u8fdb\u884c\u8fde\u63a5\uff1a\\n\\n``` css\\n.tree ul li::before{\\n  content      : \'\';\\n  display      : block;\\n  position     : absolute;\\n  top          : calc(var(--spacing) / -2);\\n  left         : -2px;\\n  width        : calc(var(--spacing) + 2px);\\n  height       : calc(var(--spacing) + 1px);\\n  border       : solid #ddd;\\n  border-width : 0 0 2px 2px;\\n}\\n```\\n\\n\u8fd9\u6bb5 CSS \u4ee3\u7801\u540c\u65f6\u4e5f\u751f\u6210\u4e86\u4e00\u5c0f\u6bb5\u5782\u76f4\u65b9\u5411\u7684\u7ebf\u6761\u548c\u4e4b\u524d\u7684\u5782\u76f4\u7ebf\u6761\u91cd\u5408\u4e86\uff0c\u5f25\u8865\u4e86\u5782\u76f4\u7ebf\u548c\u6c34\u5e73\u7ebf\u4e4b\u95f4\u7684\u4e00\u5c0f\u6bb5\u95f4\u9699\u3002\u7ebf\u6761\u662f\u901a\u8fc7\u4f2a\u5143\u7d20\u8bbe\u7f6e\u6210\u77e9\u5f62\uff0c\u7136\u540e\u6dfb\u52a0\u5de6\u4fa7\u548c\u5e95\u90e8\u8fb9\u6846\u5b9e\u73b0\u7684\u3002\\n\\n<TreeViews ulClsName=\'displayVLineTree\' expandAll={ true } />\\n\\n#### \u5c55\u5f00\u9879\\n\\n\u4e0b\u9762\u6211\u4eec\u79fb\u9664 `summary` \u5143\u7d20\u81ea\u5e26\u9ed8\u8ba4\u7684\u7bad\u5934\u56fe\u6807\\n\\n``` css\\n.tree summary{\\n  display : block;\\n  cursor  : pointer;\\n}\\n\\n.tree summary::marker,\\n.tree summary::-webkit-details-marker{\\n  display : none;\\n}\\n\\n.tree summary:focus{\\n  outline : none;\\n}\\n\\n.tree summary:focus-visible{\\n  outline : 1px dotted #000;\\n}\\n```\\n\\n\u4e3a\u5143\u7d20 `summary` \u8bbe\u7f6e `display: block` \u662f\u4e3a\u4e86\u79fb\u9664\u9ed8\u8ba4\u7684\u524d\u9762\u7684\u7bad\u5934\u7b26\u53f7\u3002\u4e0b\u9762\u90a3\u6bb5\u7ed9 `::marker` \u8bbe\u7f6e\u7684 `display: none` \u4e3a\u89e3\u51b3 Safari \u6d4f\u89c8\u5668\u7684\u517c\u5bb9\u6027\u3002Safari \u6d4f\u89c8\u5668\u5728 `summary` \\n\u5468\u56f4\u663e\u793a\u4e86\u7126\u70b9\u6307\u793a\u5668\uff0c\u5373\u4f7f\u9f20\u6807\u6307\u9488\u800c\u4e0d\u662f\u952e\u76d8\u5bfc\u822a\u65f6\u4e5f\u662f\u5982\u6b64\uff0c\u56e0\u6b64\u6211\u4eec\u5220\u9664\u4e86\u5b83\u7684 `focus` \u72b6\u6001\u6837\u5f0f\uff0c\u7136\u540e\u4f7f\u7528 `:focus-visible` \u4f2a\u7c7b\u4e3a\u4f7f\u7528\u952e\u76d8\u5bfc\u822a\u7684\u8bbf\u95ee\u8005\u6dfb\u52a0\u56de\u6765\u3002\\n\\n\u6dfb\u52a0\u540e\u7684\u6837\u5f0f\uff1a\\n\\n<TreeViews ulClsName=\'displayArrowTree\' expandAll={ true } />\\n\\n#### \u6dfb\u52a0\u6811\u8282\u70b9\u7b26\u53f7\\n\\n\u6211\u4eec\u4f7f\u7528 [CSS \u751f\u6210\u5185\u5bb9](https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_Generated_Content)\u6765\u521b\u5efa\u6811\u8282\u70b9\u7684\u6307\u793a\u7b26\u53f7\\n\\n``` css\\n.tree li::after,\\n.tree summary::before{\\n  content       : \'\';\\n  display       : block;\\n  position      : absolute;\\n  top           : calc(var(--spacing) / 2 - var(--radius));\\n  left          : calc(var(--spacing) - var(--radius) - 1px);\\n  width         : calc(2 * var(--radius));\\n  height        : calc(2 * var(--radius));\\n  border-radius : 50%;\\n  background    : #ddd;\\n}\\n```\\n\\n\u8fd9\u91cc\u6211\u4eec\u5229\u7528\u4f2a\u5143\u7d20\u540c\u65f6\u7ed9 `li` \u548c `summary` \u4e24\u4e2a\u5143\u7d20\u6dfb\u52a0\u4e86\u5706\u5f62\u7b26\u53f7\uff0c\u7531\u4e8e\u4f7f\u7528\u4e86\u7edd\u5bf9\u5b9a\u4f4d\uff0c\u4ed6\u4eec\u91cd\u5408\u5728\u4e00\u8d77\u3002top \u548c left \u7684\u503c\u6b63\u597d\u8ba9\u8fd9\u4e2a\u5706\u70b9\u7684\u5706\u5fc3\u5904\u4e8e\u5782\u76f4\u548c\u6c34\u5e73\u76f8\u4ea4\u7ebf\u7684\u89d2\u4e0a\u3002\\n\\n\u5e94\u7528\u6837\u5f0f\u540e\u663e\u793a\u5982\u4e0b\uff1a\\n\\n<TreeViews ulClsName=\'displayDotTree\' expandAll={ true } />\\n\\n#### \u5c55\u5f00\u6536\u7f29\u6309\u94ae\\n\\n\u6700\u540e\u6211\u4eec\u5b9e\u73b0\u5c55\u5f00\u6536\u7f29\u6309\u94ae\\n\\n``` css\\n.tree summary::before{\\n  content     : \'+\';\\n  z-index     : 1;\\n  background  : #696;\\n  color       : #fff;\\n  line-height : calc(2 * var(--radius) - 2px);\\n  text-align  : center;\\n}\\n\\n.tree details[open] > summary::before{\\n  content : \'\u2212\';\\n}\\n```\\n\\n\u5e94\u7528\u5b8c\u4e0a\u9762\u6837\u5f0f\u540e\uff0c\u6548\u679c\u5982\u4e0b\uff1a\\n\\n<TreeViews ulClsName=\'displaytree\' expandAll={ true } />\\n\\n### \u6700\u540e\\n\\n\u5b8c\u6574\u7684\u6837\u5f0f\u4ee3\u7801\\n\\n``` css\\n.tree{\\n  --spacing : 1.5rem;\\n  --radius  : 10px;\\n}\\n\\n.tree li{\\n  display      : block;\\n  position     : relative;\\n  padding-left : calc(2 * var(--spacing) - var(--radius) - 2px);\\n}\\n\\n.tree ul{\\n  margin-left  : calc(var(--radius) - var(--spacing));\\n  padding-left : 0;\\n}\\n\\n.tree ul li{\\n  border-left : 2px solid #ddd;\\n}\\n\\n.tree ul li:last-child{\\n  border-color : transparent;\\n}\\n\\n.tree ul li::before{\\n  content      : \'\';\\n  display      : block;\\n  position     : absolute;\\n  top          : calc(var(--spacing) / -2);\\n  left         : -2px;\\n  width        : calc(var(--spacing) + 2px);\\n  height       : calc(var(--spacing) + 1px);\\n  border       : solid #ddd;\\n  border-width : 0 0 2px 2px;\\n}\\n\\n.tree summary{\\n  display : block;\\n  cursor  : pointer;\\n}\\n\\n.tree summary::marker,\\n.tree summary::-webkit-details-marker{\\n  display : none;\\n}\\n\\n.tree summary:focus{\\n  outline : none;\\n}\\n\\n.tree summary:focus-visible{\\n  outline : 1px dotted #000;\\n}\\n\\n.tree li::after,\\n.tree summary::before{\\n  content       : \'\';\\n  display       : block;\\n  position      : absolute;\\n  top           : calc(var(--spacing) / 2 - var(--radius));\\n  left          : calc(var(--spacing) - var(--radius) - 1px);\\n  width         : calc(2 * var(--radius));\\n  height        : calc(2 * var(--radius));\\n  border-radius : 50%;\\n  background    : #ddd;\\n}\\n\\n.tree summary::before{\\n  content     : \'+\';\\n  z-index     : 1;\\n  background  : #696;\\n  color       : #fff;\\n  line-height : calc(2 * var(--radius) - 2px);\\n  text-align  : center;\\n}\\n\\n.tree details[open] > summary::before{\\n  content : \'\u2212\';\\n}\\n```"},{"id":"detecting-caps-lock","metadata":{"permalink":"/blog/detecting-caps-lock","source":"@site/blog/2023-05-25-detecting-caps-lock.mdx","title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","description":"\u5f00\u53d1\u4e2d\u4e3a\u4e86\u63d0\u5347\u7f51\u9875\u7684\u53ef\u7528\u6027\uff0c\u5728\u7f51\u9875\u4e2d\u68c0\u6d4b\u952e\u76d8\u5927\u5c0f\u5199\u952e caps lock \u5f00\u542f\u72b6\u6001\u5f88\u6709\u5fc5\u8981\uff0c\u5c24\u5176\u5728\u8f93\u5165\u5bc6\u7801\u7684\u65f6\u5019\uff0c\u6211\u4eec\u5e76\u4e0d\u80fd\u770b\u89c1\u8f93\u5165\u7684\u5b57\u7b26\u662f\u4ec0\u4e48\uff0c\u5982\u679c\u662f\u7531\u4e8e\u5927\u5c0f\u5199\u9519\u8bef\u6211\u4eec\u5e76\u4e0d\u80fd\u7b2c\u4e00\u65f6\u95f4\u611f\u77e5\u5230\u3002","date":"2023-05-25T00:00:00.000Z","formattedDate":"2023\u5e745\u670825\u65e5","tags":[{"label":"\u4fa6\u542c","permalink":"/blog/tags/\u4fa6\u542c"},{"label":"Capslock","permalink":"/blog/tags/capslock"}],"readingTime":2.355,"hasTruncateMarker":false,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=32&v=4","key":"timfan"}],"frontMatter":{"slug":"detecting-caps-lock","title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","authors":["timfan"],"tags":["\u4fa6\u542c","Capslock"]},"prevItem":{"title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","permalink":"/blog/tree-views"}},"content":"\u5f00\u53d1\u4e2d\u4e3a\u4e86\u63d0\u5347\u7f51\u9875\u7684\u53ef\u7528\u6027\uff0c\u5728\u7f51\u9875\u4e2d\u68c0\u6d4b\u952e\u76d8\u5927\u5c0f\u5199\u952e `caps lock` \u5f00\u542f\u72b6\u6001\u5f88\u6709\u5fc5\u8981\uff0c\u5c24\u5176\u5728\u8f93\u5165\u5bc6\u7801\u7684\u65f6\u5019\uff0c\u6211\u4eec\u5e76\u4e0d\u80fd\u770b\u89c1\u8f93\u5165\u7684\u5b57\u7b26\u662f\u4ec0\u4e48\uff0c\u5982\u679c\u662f\u7531\u4e8e\u5927\u5c0f\u5199\u9519\u8bef\u6211\u4eec\u5e76\u4e0d\u80fd\u7b2c\u4e00\u65f6\u95f4\u611f\u77e5\u5230\u3002\\n\\n\u5982\u4e0b\u5b9e\u4f8b\u6f14\u793a\uff0c\u5f53\u6211\u4eec\u5728\u5bc6\u7801\u8f93\u5165\u6846\u4e2d\u8f93\u5165\u5185\u5bb9\u65f6\uff0c\u5982\u679c\u6211\u4eec\u7684\u5927\u5c0f\u5199\u952e\u662f\u5f00\u542f\u7684\u72b6\u6001\uff0c\u5c31\u4f1a\u5f97\u5230\u201cCaps lock is on\u201d\u8fd9\u6837\u7684\u63d0\u793a\u4fe1\u606f\u3002\\n\\nimport { useState } from \'react\'\\nimport BrowserOnly from \'@docusaurus/BrowserOnly\'\\nexport const CapsLockDetect = () => {\\n  return (\\n    <BrowserOnly>\\n    {() => {\\n      const [ locked, setLocked ] = useState(false);\\n      window.addEventListener(\'keydown\', detect)\\n      window.addEventListener(\'keyup\', detect)\\n      function detect (e) {\\n        if (e.getModifierState(\'CapsLock\')) {\\n          setLocked(true)\\n        } else {\\n          setLocked(false)\\n        }\\n      }\\n      return (\\n        <div\\n          style={{\\n            backgroundColor: \'#eee\',\\n            padding: \'10px\',\\n            margin: \'0 0 20px\'\\n          }}>\\n          <input type=\'password\' placeholder=\\"Password\\" />\\n          { locked ? <div>Caps lock is on</div> : \'\' }\\n        </div>\\n      )\\n    }}\\n    </BrowserOnly>\\n  )\\n};\\n\\n<CapsLockDetect />\\n\\n\u867d\u7136\u76ee\u524d\u6d4f\u89c8\u5668\u8fd8\u6ca1\u6709\u63d0\u4f9b\u73b0\u6210\u7684 API \u6765\u67e5\u8be2 `caps lock` \u952e\u7684\u5f00\u542f\u7684\u72b6\u6001\uff0c\u4f46\u662f\u6211\u4eec\u53ef\u4ee5\u91c7\u7528\u5bf9\u6309\u952e `keyup` \u548c `keydown` \u4e8b\u4ef6\u7684\u76d1\u542c\uff0c\u7136\u540e\u901a\u8fc7 `KeyboardEvent` \u5bf9\u8c61\u7684\\n [getModifierState](https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/getModifierState) \u65b9\u6cd5\u6765\u83b7\u53d6\u3002\\n\\n\\n``` js\\nwindow.addEventListener(\'keydown\', detectCapsLock)\\nwindow.addEventListener(\'keyup\', detectCapsLock)\\n\\nfunction detectCapsLock(e) {\\n  if (e.getModifierState(\'CapsLock\')) {\\n    // caps lock is on\\n  } else {\\n    // caps lock is off\\n  }\\n}\\n```\\n\\n\u6211\u4eec\u5fc5\u987b\u540c\u65f6\u76d1\u542c `keyup` \u548c `keydown` \u6309\u952e\u4e8b\u4ef6\uff0c\u56e0\u4e3a\uff0c\u901a\u5e38\u60c5\u51b5\u4e0b\uff0c\u6d4f\u89c8\u5668\u4f1a\u5728\u67d0\u4e2a\u6309\u952e\u6309\u4e0b\u65f6\u89e6\u53d1 `keydown` \u4e8b\u4ef6\uff0c\u5728\u91ca\u653e\u8be5\u952e\u65f6\u89e6\u53d1 `keyup` \u4e8b\u4ef6\uff0c\u4f46\u662f\u5bf9\u4e8e\u952e\u76d8\u4e0a\u7684 `caps lock` \u952e\u800c\u8a00\uff0c\\n\u6bcf\u6b21\u6309\u4e0b\u53ea\u4f1a\u89e6\u53d1\u5176\u4e2d\u7684\u4e00\u4e2a\u4e8b\u4ef6\u3002\\n\\n\u5f53\u6211\u4eec\u6309\u4e0b `caps lock` \u952e\u4ee5\u6253\u5f00\u5927\u5199\u9501\u5b9a\u65f6\uff0c\u6240\u6709\u6d4f\u89c8\u5668\u4ec5\u53d1\u9001\u4e00\u4e2a keydown \u4e8b\u4ef6\u3002\u5f53\u6211\u4eec\u6309\u4e0b `caps lock` \u952e\u4ee5\u5173\u95ed\u5927\u5199\u9501\u5b9a\u65f6\uff0cFirefox \u6d4f\u89c8\u5668\u53ea\u89e6\u53d1\u4e86 `keydown` \u4e8b\u4ef6\uff0c\u4f46\u662f Chrome\u3001Safari \u548c\\n Edge \u53ea\u4f1a\u89e6\u53d1 `keyup` \u4e8b\u4ef6\uff08\u5176\u5b9e\u5c31\u76f8\u5f53\u4e8e\u5728\u5927\u5199\u5f00\u542f\u72b6\u6001\u4e0b\uff0c`Shift` \u952e\u88ab\u540c\u65f6\u6309\u4e0b\uff09\u3002"}]}')}}]);